import { test, expect } from "vitest";
import { createHmac } from "node:crypto";
import { verifyToken } from "../src/auth/jwt";

const b64 = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (header: object, payload: object, secret = "k") => {
  const data = `${b64(header)}.${b64(payload)}`;
  return `${data}.${createHmac("sha256", secret).update(data).digest("base64url")}`;
};
const now = Math.floor(Date.now() / 1000);

test("accepts a valid unexpired token", () => {
  expect(verifyToken(sign({ alg: "HS256" }, { sub: "u", exp: now + 60 }), "k")).toEqual({ sub: "u", exp: now + 60 });
});

test("rejects expired tokens", () => {
  expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u", exp: now - 1 }), "k")).toThrow("expired");
});

test("rejects tokens signed with a different secret", () => {
  expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u", exp: now + 60 }, "x"), "k")).toThrow("signature");
});

test("rejects alg none bypass", () => {
  expect(() => verifyToken(`${b64({ alg: "none" })}.${b64({ sub: "u", exp: now + 60 })}.`, "k")).toThrow("alg");
});

test("rejects privilege escalation via tampered payload", () => {
  const [h, , s] = sign({ alg: "HS256" }, { sub: "u", exp: now + 60 }).split(".");
  expect(() => verifyToken(`${h}.${b64({ sub: "admin", exp: now + 60 })}.${s}`, "k")).toThrow("signature");
});

test("rejects tokens without an expiry", () => {
  expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u" }), "k")).toThrow("claims");
});

